describe('ToolRegistry dynamic schemas', () => {
  it('validates each resolved schema and reuses validators for the same schema object [specs/hal-engine-tool-input-validation/spec.md#7]', async () => {
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const locationSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const unitSchema = {
      type: 'object',
      properties: {unit: {type: 'string'}},
      required: ['unit'],
    };
    let currentSchema = locationSchema;
    const executor = jest.fn(async () => 'ok');
    registry.register(() => ({name: 'weather', description: 'Weather', inputSchema: currentSchema}), executor);

    try {
      expect((await registry.execute('weather', {})).result).toContain('location');
      currentSchema = unitSchema;
      expect((await registry.execute('weather', {})).result).toContain('unit');
      expect((await registry.execute('weather', {})).result).toContain('unit');
      expect(executor).not.toHaveBeenCalled();
      expect(compile).toHaveBeenCalledTimes(2);
    } finally {
      compile.mockRestore();
    }
  });
});
